func editDistance(s1, s2) = {
  local m = s1.textLen()
  local n = s2.textLen()
  local dp = []
  for (i: 0 .. m) {
    local row = []
    for (j: 0 .. n) { row.add(0) }
    dp.add(row)
  }
  for (i: 0 .. m) { dp[i][1] = i }
  for (j: 0 .. n) { dp[1][j] = j }
  for (i: 2 .. m + 1) {
    for (j: 2 .. n + 1) {
      if (s1.segment(i-1,1) === s2.segment(j-1,1)) {
        dp[i][j] = dp[i-1][j-1]
      } else {
        local a = dp[i-1][j] + 1
        local b = dp[i][j-1] + 1
        local c = dp[i-1][j-1] + 1
        dp[i][j] = if (a < b && a < c) a else if (b < c) b else c
      }
    }
  }
  dp[m+1][n+1]
}
